1701 |     // ========================================================================
1702 |     // Output Stage Signals
1703 |     // ========================================================================
1704 |     reg [DATA_WIDTH-1:0] Q_tmp;
1705 |     reg                  q_fast_update;
1706 | 
1707 |     initial begin
1708 |         Q_tmp               = {DATA_WIDTH{1'bx}};
1709 |         q_fast_update             = 1'b1;
1710 |     end
1711 | 
1712 |     // ========================================================================
1713 |     // Column Redundancy (direct-pin interface, v8.0)
1714 |     //
1715 |     // CRSLE / CRSLA[CR_ADDR_WIDTH-1:0] : left CR enable + defect IO index
1716 |     // CRSRE / CRSRA[CR_ADDR_WIDTH-1:0] : right CR enable + defect IO index
1717 |     // CR pins are asynchronous (no clock sync); must be stable during R/W.
1718 |     //
1719 |     // SD (CD=0): only CRSRE/CRSRA used. spare (memoryIO) at LSB side (MEM[0]).
1720 |     //   defect IO index a -> IO<0>=memoryIO, IO<i>=mem<i-1> (1<=i<=a), mem<a> skipped.
1721 |     //   CRSLE/CRSLA ignored (no spare on left in SD mode).
1722 |     //
1723 |     // CD (CD=1): left mem uses CRSLE/CRSLA, right mem uses CRSRE/CRSRA, independent.
1724 |     //   Left  (up-shift,  spare at MSB of left):
1725 |     //       IO<i>=mem_L<i> (i<a); IO<i>=mem_L<i+1> (a<=i<NB2_L-1);
1726 |     //       IO<NB2_L-1>=memoryIO_L; mem_L<a> skipped.
1727 |     //   Right (down-shift, spare at LSB of right):
1728 |     //       IO<0>=memoryIO_R; IO<i>=mem_R<i-1> (1<=i<=a);
1729 |     //       IO<i>=mem_R<i> (i>a); mem_R<a> skipped.
1730 |     //
1731 |     // Out-of-range address (>= actual column count) -> CR ineffective (no shift).
1732 |     // When EN_COLRED=0, all CR pins ignored.
1733 |     // ========================================================================
1734 | 
1735 |     // Effective CR enables (level-gated, no internal latch).
1736 |     // CRSxE is used as a live level gate (=== 1'b1), not an edge-triggered latch.
1737 |     // Uses live CRSxA port value for range check (MBIST shift: address changes
1738 |     // while CRSxE=1, so range check must follow live value). Aligns with 2P_SRAM
1739 |     // and industry standard practice (no CK-edge latch on redundancy signals).
1740 |     wire crsle_eff = EN_COLRED && (CRSLE_buf === 1'b1) &&
1741 |                      (CENTER_DECODE == 1) && (^CRSLA !== 1'bx) &&
1742 |                      (CRSLA < NB2_L);
1743 |     wire crsre_eff = EN_COLRED && (CRSRE_buf === 1'b1) &&
1744 |                      (^CRSRA !== 1'bx) &&
1745 |                      (CRSRA < (CENTER_DECODE ? NB2_R : DATA_WIDTH));
1746 | 
1747 |     // Column shift is actually happening (defect in range, CRSxE latched).
1748 |     // Used to select tr* timing params over t* in behavioral checks and Q path.
1749 |     // (cr_shift_active declared earlier, near Q output block, for forward-ref.)
1750 |     assign cr_shift_active = (crsle_eff || crsre_eff);
1751 | 
1752 |     // Effective timing params: tr* when CR shift active, else t*.
1753 |     // Used by behavioral setup/hold checks (always blocks below).
1754 |     // (*_eff variables declared earlier, near Q output block, for forward-ref.)
1755 |     // (specify block uses separate $setuphold pairs with &&& conditions --
1756 |     //  specparam must be constant, so it cannot reference these variables.)
1757 |     always @* begin
1758 |         tas_eff  = cr_shift_active ? tras  : tas;
1759 |         tah_eff  = cr_shift_active ? trah  : tah;
1760 |         tws_eff  = cr_shift_active ? trws  : tws;
1761 |         twh_eff  = cr_shift_active ? trwh  : twh;
1762 |         tbws_eff = cr_shift_active ? trbws : tbws;
1763 |         tbwh_eff = cr_shift_active ? trbwh : tbwh;
1764 |         tds_eff  = cr_shift_active ? trds  : tds;
1765 |         tdh_eff  = cr_shift_active ? trdh  : tdh;
1766 |         tcs_eff  = cr_shift_active ? trcs  : tcs;
1767 |         tch_eff  = cr_shift_active ? trch  : tch;
1768 |     end
1769 | 
1770 |     // Integer indices for use in tasks (tasks can't read wire directly in all tools)
1771 |     // Decoded into integer regs via continuous assign workaround: use wires + pass
1772 |     // directly to tasks as integer via $unsigned.
1773 |     // We pass CRSLA_buf / CRSRA_buf directly to the Colmun tasks.
1774 | 
1775 |     // ========================================================================
1776 |     // Column Redundancy Helper Tasks (v8.0 direct-pin interface)
1777 |     //
1778 |     // Four shift-direction tasks. Each takes a defect index `a` (the IO index
1779 |     // of the defective column, -1 = CR not active) and produces the expanded
1780 |     // (read) or compressed (write) mapping. spare storage (memoryIO) is passed
1781 |     // in separately.
1782 |     //
1783 |     // CRReadDownShift : spare at LSB. IO<0..gs-1>=spare, IO<i>=mem<i-gs> (gs<=i<=a).
1784 |     //                   Used by SD (CD=0) and CD right mem.
1785 |     // CRReadUpShift   : spare at MSB. IO<i>=mem<i> (i<a), IO<i>=mem<i+gs> (a<=i<N-gs),
1786 |     //                   IO<N-gs..N-1>=spare. Used by CD left mem.
1787 |     // CRWriteDownShift / CRWriteUpShift : inverse of the read tasks.
1788 |     // v12.6: gs (group size) = SPARE_WIDTH. CM=1 -> gs=2 (2-bit group repair);
1789 |     //        CM!=1 -> gs=1 (1-bit repair, identical to v12.5).
1790 |     //        CRSxA indexes individual bit; group g = a / gs.
1791 |     // ========================================================================
1792 |     reg [DATA_WIDTH-1:0] colred_read_result;
1793 | 
1794 |     // --- Down-shift read (spare at LSB group). a = defect IO index. ---
1795 |     // gs=1: IO<0>=spare; IO<i>=mem<i-1> (1<=i<=a); IO<i>=mem<i> (i>a); mem<a> skipped.
1796 |     // gs=2: IO<0,1>=spare[0,1]; IO<i>=mem<i-2> (2<=i<=2g+1); IO<i>=mem<i> (i>=2g+2);
1797 |     //       mem<2g,2g+1> skipped (defect group).
1798 |     // General: group 0 = spare; groups 1..g shift by gs; groups g+1..end no shift.
1799 |     // N = width (DATA_WIDTH for SD, NB2_R for CD right mem).
1800 |     task CRReadDownShift;
1801 |         input integer a;                 // defect IO index (-1 = inactive)
1802 |         input integer n;                 // width of this mem
1803 |         input [DATA_WIDTH-1:0] memdata;  // main memory word (uses [n-1:0])
1804 |         input [1:0] sparetap;            // memoryIO spare bits ([SPARE_WIDTH-1:0] used)
1805 |         integer i, k;
1806 |         integer gs, g;
1807 |         reg [DATA_WIDTH-1:0] result;
1808 |     begin
1809 |         gs = SPARE_WIDTH;
1810 |         if (a < 0) begin
1811 |             colred_read_result = memdata;
1812 |         end else begin
1813 |             g = a / gs;  // defect group index
1814 |             result = {DATA_WIDTH{1'bx}};
1815 |             // Group 0: spare
1816 |             for (k = 0; k < gs; k = k + 1)
1817 |                 result[k] = sparetap[k];
1818 |             // Groups 1..g: shift down by gs (IO<i> = mem<i-gs>)
1819 |             for (i = gs; i <= g*gs + gs - 1; i = i + 1)
1820 |                 result[i] = memdata[i-gs];
1821 |             // Groups g+1..end: no shift (IO<i> = mem<i>)
1822 |             for (i = g*gs + gs; i < n; i = i + 1)
1823 |                 result[i] = memdata[i];
1824 |             // bits [n : DATA_WIDTH-1] stay X (unused for this half)
1825 |             colred_read_result = result;
1826 |         end
1827 |     end
1828 |     endtask
1829 | 
1830 |     // --- Down-shift write (spare at LSB group). a = defect IO index. ---
1831 |     // Inverse of read: spare=D<0..gs-1>; mem<j>=D<j+gs> (0<=j<=g*gs-1);
1832 |     //   mem<g*gs..g*gs+gs-1>=skip; mem<j>=D<j> (g*gs+gs<=j<=n-1).
1833 |     // N = width (DATA_WIDTH for SD, NB2_R for CD right mem).
1834 |     // Returns compressed main-mem word in colred_write_result and spare bits in
1835 |     // colred_write_spare ([SPARE_WIDTH-1:0] used).
1836 |     reg [DATA_WIDTH-1:0] colred_write_result;
1837 |     reg [SPARE_WIDTH-1:0] colred_write_spare;
1838 | 
1839 |     task CRWriteDownShift;
1840 |         input integer a;
1841 |         input integer n;
1842 |         input [DATA_WIDTH-1:0] writedata;
1843 |         input [DATA_WIDTH-1:0] curmem;
1844 |         integer i, k;
1845 |         integer gs, g;
1846 |         reg [DATA_WIDTH-1:0] result;
1847 |     begin
1848 |         gs = SPARE_WIDTH;
1849 |         if (a < 0) begin
1850 |             colred_write_result = writedata;
1851 |             colred_write_spare  = {SPARE_WIDTH{1'bx}};
1852 |         end else begin
1853 |             g = a / gs;
1854 |             result = curmem;
1855 |             // spare = D<0..gs-1>
1856 |             for (k = 0; k < gs; k = k + 1)
1857 |                 colred_write_spare[k] = writedata[k];
1858 |             // mem<j> = D<j+gs> (j < g*gs, shift down)
1859 |             for (i = 0; i <= g*gs - 1; i = i + 1)
1860 |                 result[i] = writedata[i+gs];
1861 |             // result[g*gs .. g*gs+gs-1] preserved as curmem (defective group, skip)
1862 |             // mem<j> = D<j> (j >= g*gs+gs, no shift)
1863 |             for (i = g*gs + gs; i < n; i = i + 1)
1864 |                 result[i] = writedata[i];
1865 |             colred_write_result = result;
1866 |         end
1867 |     end
1868 |     endtask
1869 | 
1870 |     // --- Up-shift read (spare at MSB group). a = defect IO index. ---
1871 |     // gs=1: IO<i>=mem<i> (i<a); IO<i>=mem<i+1> (a<=i<N-1); IO<N-1>=spare. mem<a> skipped.
1872 |     // gs=2: IO<i>=mem<i> (i<2g); IO<i>=mem<i+2> (2g<=i<N-2); IO<N-2,N-1>=spare.
1873 |     //       mem<2g,2g+1> skipped (defect group).
1874 |     // General: groups 0..g-1 no shift; groups g..ngroups-2 shift by gs;
1875 |     //          last group = spare.
1876 |     // N = width (NB2_L for CD left mem). mem<N-gs..N-1> unused in main mem (spare in memoryIO).
1877 |     task CRReadUpShift;
1878 |         input integer a;
1879 |         input integer n;                 // width of this mem
1880 |         input [DATA_WIDTH-1:0] memdata;  // main memory word (uses [n-1:0])
1881 |         input [1:0] sparetap;
1882 |         integer i, k;
1883 |         integer gs, g;
1884 |         reg [DATA_WIDTH-1:0] result;
1885 |     begin
1886 |         gs = SPARE_WIDTH;
1887 |         if (a < 0) begin
1888 |             colred_read_result = memdata;
1889 |         end else begin
1890 |             g = a / gs;
1891 |             result = {DATA_WIDTH{1'bx}};
1892 |             // Groups 0..g-1: no shift (IO<i> = mem<i>)
1893 |             for (i = 0; i < g*gs; i = i + 1)
1894 |                 result[i] = memdata[i];
1895 |             // Groups g..ngroups-2: shift up by gs (IO<i> = mem<i+gs>)
1896 |             for (i = g*gs; i < n - gs; i = i + 1)
1897 |                 result[i] = memdata[i+gs];
1898 |             // Last group: spare
1899 |             for (k = 0; k < gs; k = k + 1)
1900 |                 result[n - gs + k] = sparetap[k];
1901 |             // bits [n : DATA_WIDTH-1] stay X (unused for this half)
1902 |             colred_read_result = result;
1903 |         end
1904 |     end
1905 |     endtask
1906 | 
1907 |     // --- Up-shift write (spare at MSB group). a = defect IO index. ---
1908 |     // gs=1: mem<i>=D<i> (i<a); mem<a>=skip; mem<i>=D<i-1> (a<i<=n-1); spare=D<n-1>.
1909 |     // gs=2: mem<i>=D<i> (i<2g); mem<2g,2g+1>=skip; mem<i>=D<i-2> (2g+2<=i<=n-1);
1910 |     //       spare=D<n-2,n-1>.
1911 |     // General: groups 0..g-1 no shift; group g skip; groups g+1..ngroups-1 shift;
1912 |     //          last group = spare.
1913 |     task CRWriteUpShift;
1914 |         input integer a;
1915 |         input integer n;
1916 |         input [DATA_WIDTH-1:0] writedata;
1917 |         input [DATA_WIDTH-1:0] curmem;
1918 |         integer i, k;
1919 |         integer gs, g;
1920 |         reg [DATA_WIDTH-1:0] result;
1921 |     begin
1922 |         gs = SPARE_WIDTH;
1923 |         if (a < 0) begin
1924 |             colred_write_result = writedata;
1925 |             colred_write_spare  = {SPARE_WIDTH{1'bx}};
1926 |         end else begin
1927 |             g = a / gs;
1928 |             result = curmem;
1929 |             // spare = D<n-gs..n-1>
1930 |             for (k = 0; k < gs; k = k + 1)
1931 |                 colred_write_spare[k] = writedata[n - gs + k];
1932 |             // mem<i> = D<i> (i < g*gs, no shift)
1933 |             for (i = 0; i < g*gs; i = i + 1)
1934 |                 result[i] = writedata[i];
1935 |             // result[g*gs .. g*gs+gs-1] preserved as curmem (defective group, skipped)
1936 |             // mem<i> = D<i-gs> (i >= g*gs+gs, up-shift)
1937 |             for (i = g*gs + gs; i <= n-1; i = i + 1)
1938 |                 result[i] = writedata[i-gs];
1939 |             colred_write_result = result;
1940 |         end
1941 |     end
1942 |     endtask
1943 | 
1944 |     // ========================================================================
1945 |     // Fault Injection: apply XOR/SA0/SA1 to raw mem data before CR shift.
1946 |     //   XOR mode (FAULT_INJ):  fi_result = mem ^ XOR array
1947 |     //   SA0/SA1 mode (default):  fi_result = (mem & sa0) | sa1  (no-op)
1948 |     // Called from read path in sram_op_exec, before CRReadDownShift/etc.
1949 |     // ========================================================================
1950 |     function [DATA_WIDTH-1:0] apply_fi;
1951 |         input [DATA_WIDTH-1:0] raw_data;
1952 |         input [ADDR_WIDTH-1:0] addr;
1953 |         begin
1954 |             if (fi_enable)
1955 |                 apply_fi = raw_data ^ fi_xor_mask[addr];
1956 |             else
1957 |                 apply_fi = (raw_data & fi_and_mask[addr]) |
1958 |                                         fi_or_mask[addr];
1959 |         end
1960 |     endfunction
1961 | 
1962 |     // ========================================================================
1963 |     // Memory Storage & Column Redundancy - generate blocks for hierarchical access
1964 |     //
1965 |     // All storage arrays are declared at MODULE LEVEL (not inside generate)
1966 |     // so that Verdi/FSDB can access them directly as dut.mem, dut.memoryIO, etc.
1967 |     // without needing to expand generate-block hierarchy.
1968 |     // ========================================================================
1969 |     integer i_init;
1970 | 
1971 |     // (mem, mem_L, mem_R, memoryIO, memoryIO_L, memoryIO_R declared earlier
1972 |     //  for CR edge detection blocks -- VCS declaration order requirement)
1973 | 
1974 |     generate if (CENTER_DECODE == 0) begin : gen_sd
1975 | 
1976 |         // ---- SD mode: Memory & Shift Register ----
1977 |         // (mem, memoryIO declared at module level for Verdi visibility)
1978 | 
1979 |         initial begin
1980 |             for (i_init = 0; i_init < DEPTH; i_init = i_init + 1) begin
1981 |                 mem[i_init]      = INIT_TO_X ? {DATA_WIDTH{1'bx}} : {DATA_WIDTH{1'b0}};
1982 |                 memoryIO[i_init] = INIT_TO_X ? {SPARE_WIDTH{1'bx}} : {SPARE_WIDTH{1'b0}};
1983 |             end
1984 |         end
1985 | 
1986 |         // ---- SD mode: mem_init task ----
1987 |         task mem_init;
1988 |             input ini_value;
1989 |             reg   ini_value;
1990 |             integer k;
1991 |         begin
1992 |             if (ini_value === 1'bx) begin
1993 |                 for (k = 0; k < DEPTH; k = k + 1) begin
1994 |                     mem[k]      <= {DATA_WIDTH{1'bx}};
1995 |                     memoryIO[k] <= {SPARE_WIDTH{1'bx}};
1996 |                 end
1997 |             end else if (ini_value === 1'b1) begin
1998 |                 for (k = 0; k < DEPTH; k = k + 1) begin
1999 |                     mem[k]      <= {DATA_WIDTH{1'b1}};
2000 |                     memoryIO[k] <= {SPARE_WIDTH{1'b1}};
2001 |                 end
2002 |             end else if (ini_value === 1'b0) begin
2003 |                 for (k = 0; k < DEPTH; k = k + 1) begin
2004 |                     mem[k]      <= {DATA_WIDTH{1'b0}};
2005 |                     memoryIO[k] <= {SPARE_WIDTH{1'b0}};
2006 |                 end
2007 |             end
2008 |         end
2009 |         endtask
2010 | 
2011 |         // ---- SD mode: sram_op_exec task ----
2012 |         task sram_op_exec;
2013 |             integer j;
2014 |         begin
2015 |             // --- CR latch corruption (CRSxE rose since last CLK) ---
2016 |             if (cr_corrupt_pending) begin
2017 |                 cr_corrupt_pending = 1'b0;
2018 |                 mem_init(1'bx);
2019 |                 q_fast_update = 1'b1;
2020 |                 Q_r <= {DATA_WIDTH{1'bx}};
2021 |                 Q_force_x <= 1'b1;  // force Q to X immediately (bypass tcd)
2022 |                 if (test_mode) test_op_type = 3'd3;  // hazard/corrupt
2023 |             end else
2024 |             // --- Hazard R4/R5: CRSxE/CRSxA x/z -> all x, Q=x ---
2025 |             if ((EN_COLRED && (CRSRE_buf !== 1'b1) && (CRSRE_buf === 1'bx || CRSRE_buf === 1'bz)) ||
2026 |                 (EN_COLRED && (CRSRE_buf !== 1'b1) && (CRSRE_buf === 1'b1 && (^CRSRA_buf === 1'bx)))) begin
2027 |                 mem_init(1'bx);
2028 |                 q_fast_update = 1'b1;
2029 |                 Q_r <= {DATA_WIDTH{1'bx}};
2030 |                 Q_force_x <= 1'b1;  // force Q to X immediately (bypass tcd)
2031 |                 if (test_mode) test_op_type = 3'd3;  // hazard/corrupt
2032 |             end else
2033 |             casez({WEB_eff, CEB_eff})
2034 |                     // Write Operation
2035 |                     2'b00: begin
2036 |                         if (test_mode) test_op_type = 3'd0;  // write
2037 |                         if (^A_eff === 1'bx) begin
2038 |                             mem_init(1'bx);
2039 |                             q_fast_update = 1'b1;
2040 |                             if (test_mode) test_op_type = 3'd3;  // A=x write hazard
2041 |                         end else begin
2042 |                             if (crsre_eff) begin : sd_cr_wr
2043 |                                 // --- Column Redundancy active (SD, spare at LSB): down-shift write ---
2044 |                                 integer bw_idx;
2045 |                                 integer a;
2046 |                                 integer gs, g, sk;
2047 |                                 gs = SPARE_WIDTH;
2048 |                                 a = CRSRA;  // use live port value (MBIST shift fix)
2049 |                                 g = a / gs;  // defect group index
2050 |                                 // 1. Write memoryIO (spare = D[0..gs-1], the LSB group)
2051 |                                 for (sk = 0; sk < gs; sk = sk + 1) begin
2052 |                                     if (BWEB_eff[sk] === 1'b0)
2053 |                                         memoryIO[A_eff][sk] = (D_eff[sk] === 1'bx || D_eff[sk] === 1'bz) ? 1'bx : D_eff[sk];
2054 |                                 end
2055 |                                 // 2. Compress write data for main memory
2056 |                                 CRWriteDownShift(a, DATA_WIDTH, D_eff, mem[A_eff]);
2057 |                                 // 3. Write compressed data with BWEB mapping
2058 |                                 //    Physical mem<j> stores logical D<j+gs> (j<g*gs) or D<j> (j>=g*gs+gs);
2059 |                                 //    j in [g*gs, g*gs+gs-1] = defect group (skip).
2060 |                                 //    BWEB lookup uses logical IO index: j+gs (j<g*gs), j (j>=g*gs+gs).
2061 |                                 for (j = 0; j < DATA_WIDTH; j = j + 1) begin
2062 |                                     if (j >= g*gs && j <= g*gs + gs - 1) begin
2063 |                                         // Defective group: write X (not skipped)
2064 |                                         mem[A_eff][j] = 1'bx;
2065 |                                     end else begin
2066 |                                         if (j < g*gs)
2067 |                                             bw_idx = j + gs;   // mem<j> = D<j+gs>, check BWEB<j+gs>
2068 |                                         else
2069 |                                             bw_idx = j;        // mem<j> = D<j>, check BWEB<j>
2070 |                                         if (bw_idx >= 0 && bw_idx < DATA_WIDTH &&
2071 |                                             BWEB_eff[bw_idx] === 1'b0)
2072 |                                             mem[A_eff][j] = (colred_write_result[j] === 1'bx || colred_write_result[j] === 1'bz) ? 1'bx : colred_write_result[j];
2073 |                                         else if (bw_idx >= 0 && bw_idx < DATA_WIDTH &&
2074 |                                                  (BWEB_eff[bw_idx] === 1'bx || BWEB_eff[bw_idx] === 1'bz))
2075 |                                             mem[A_eff][j] = 1'bx;  // hazard R11
2076 |                                     end
2077 |                                 end
2078 |                             end else begin
2079 |                                 // --- No column redundancy: normal BWEB write ---
2080 |                                 for (j = 0; j < DATA_WIDTH; j = j + 1) begin
2081 |                                     if (BWEB_eff[j] === 1'b0) begin
2082 |                                         mem[A_eff][j] = (D_eff[j] === 1'bx || D_eff[j] === 1'bz) ? 1'bx : D_eff[j];
2083 |                                     end
2084 |                                     else if (BWEB_eff[j] === 1'bx || BWEB_eff[j] === 1'bz) begin
2085 |                                         mem[A_eff][j] = 1'bx;  // hazard R11: BWEB=x/z -> mem=x
2086 |                                     end
2087 |                                 end
2088 |                             end
2089 |                             q_fast_update = 1'b1;
2090 |                             // Write only stores to mem; Q keeps previous value
2091 |                         end
2092 |                     end
2093 | 
2094 |                     // Read Operation
2095 |                     2'b10: begin
2096 |                         if (test_mode) test_op_type = 3'd1;  // read
2097 |                         if (^A_eff === 1'bx) begin
2098 |                             Q_r <= {DATA_WIDTH{1'bx}};
2099 |                 Q_force_x <= 1'b1;  // force Q to X immediately (bypass tcd)  // A=x/z read: Q=X (hazard R8)
2100 |                             if (test_mode) test_op_type = 3'd3;  // A=x read hazard
2101 |                         end else begin
2102 |                             fi_result = apply_fi(mem[A_eff], A_eff);
2103 |                             if (crsre_eff) begin
2104 |                                 // Column Redundancy active (SD, spare at LSB): down-shift read
2105 |                                 CRReadDownShift(CRSRA, DATA_WIDTH, fi_result, memoryIO[A_eff]);  // live port (MBIST shift fix)
2106 |                                 Q_tmp = colred_read_result;
2107 |                             end else begin
2108 |                                 Q_tmp = fi_result;
2109 |                             end
2110 |                             if (test_mode) begin
2111 |                                 // TEST mode: store for negedge output (Q updates at negedge + tcdt)
2112 |                                 test_read_data = Q_tmp;
2113 |                             end else begin
2114 |                                 Q_r <= Q_tmp;  // Normal read
2115 |                                 Q_force_x <= 1'b0;   // clear force-x
2116 |                             end
2117 |                             q_fast_update = 1'b1;
2118 |                         end
2119 |                     end
