3092 |                         if (tckhtr > 0 && ($realtime - last_ck_rise) < tckhtr)
3093 |                             test_violation_clk = 1'b1;
3094 |                     end
3095 |                     default: ;
3096 |                 endcase
3097 | 
3098 |                 // Adjudicate based on operation type and violation flags
3099 |                 case (test_op_type)
3100 |                     3'd0: begin
3101 |                         // Write operation
3102 |                         // Q11:B: any violation -> mem = all X
3103 |                         if (test_violation_clk || test_violation_pos) begin
3104 |                             mem_init(1'bx);
3105 |                             q_fast_update = 1'b1;
3106 |                         end
3107 |                         // No violation: mem retains pre-written value (from posedge)
3108 |                     end
3109 |                     3'd1: begin
3110 |                         // Read operation
3111 |                         // Q14:A: any violation -> Q = X
3112 |                         // Also check cr_corrupt_pending: CRSxE edge between
3113 |                         // posedge and negedge invalidates pre-captured data.
3114 |                         if (test_violation_clk || test_violation_pos || cr_corrupt_pending) begin
3115 |                             Q_r <= {DATA_WIDTH{1'bx}};
3116 |                 Q_force_x <= 1'b1;  // force Q to X immediately (bypass tcd)
3117 |                         end else begin
3118 |                             // No violation: Q outputs at negedge + tcdt
3119 |                             // (v12.4: tcdt delay now via assign #(tcd) Q_normal, not Q_r NBA)
3120 |                             Q_r <= test_read_data;
3121 |                             Q_force_x <= 1'b0;   // clear force-x
3122 |                         end
3123 |                         q_fast_update = 1'b1;
3124 |                     end
3125 |                     3'd2: begin
3126 |                         // Deselect (CEB=1)
3127 |                         // Q12:B: clock-level violation -> all mem = X, Q = X
3128 |                         //         setup/hold violation -> no consequence
3129 |                         if (test_violation_clk) begin
3130 |                             mem_init(1'bx);
3131 |                             q_fast_update = 1'b1;
3132 |                             Q_r <= {DATA_WIDTH{1'bx}};
3133 |                 Q_force_x <= 1'b1;  // force Q to X immediately (bypass tcd)
3134 |                         end
3135 |                         // No clock violation: Q holds, mem unchanged
3136 |                     end
3137 |                     3'd3: begin
3138 |                         // Hazard/corrupt (CLK=x, CEB=x, WEB=x, A=x, etc.)
3139 |                         // Already handled at posedge in sram_op_exec -- nothing to do
3140 |                     end
3141 |                     default: begin
3142 |                         // Unknown state -- no action
3143 |                     end
3144 |                 endcase
3145 |             end
3146 |         end
3147 | 
3148 |     end endgenerate
