3151 |     // ========================================================================
3152 |     // Specify block condition wires: split setup/hold into normal vs CR shift
3153 |     // (specify &&& requires net expressions; specparam must be constant, so we
3154 |     //  use two $setuphold pairs with mutually exclusive conditions.)
3155 |     // ========================================================================
3156 |     wire cond_A_normal   = gate_A   && !cr_shift_active;
3157 |     wire cond_A_cr       = gate_A   && cr_shift_active;
3158 |     wire cond_D_normal   = gate_D   && !cr_shift_active;
3159 |     wire cond_D_cr       = gate_D   && cr_shift_active;
3160 |     wire cond_WEB_normal = gate_WEB && !cr_shift_active;
3161 |     wire cond_WEB_cr     = gate_WEB && cr_shift_active;
3162 |     wire cond_CEB_normal = gate_CEB && !cr_shift_active;
3163 |     wire cond_CEB_cr     = gate_CEB && cr_shift_active;
