3209 |         // Address setup/hold -- normal mode (t* params)
3210 |         genvar si;
3211 |         for (si = 0; si < ADDR_WIDTH; si = si + 1) begin : spec_A
3212 |             $setuphold (posedge eff_clk &&& cond_A_normal, posedge A[si], tas_s, tah_s, tviol_A[si]);
